"""Data quality pipeline — clean and validate records."""
import csv
import os

# Fixed rules according to specification
RULES = {
    "fill_value": "MISSING",
    "dedup_keep": "highest",
    "sort_by": "score",
    "range_min": 0,
    "range_max": 100,
}


def run():
    input_path = "data/input/records.csv"
    output_dir = "data/output"
    os.makedirs(output_dir, exist_ok=True)

    with open(input_path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Fix: dedup by id, keep highest rating
    seen_ids = {}
    for row in rows:
        rid = row["id"]
        if rid not in seen_ids or int(row["rating"]) > seen_ids[rid]["rating"]:
            seen_ids[rid] = row

    deduped = list(seen_ids.values())

    # Fix: filter by range 0-100 inclusive
    filtered = []
    for row in deduped:
        try:
            score = int(row["rating"])
            if RULES["range_min"] <= score <= RULES["range_max"]:
                filtered.append(row)
        except (ValueError, KeyError):
            continue

    # Fill missing values (empty string or N/A)
    for row in filtered:
        for key in row:
            val = row[key]
            if val == "" or val is None or val == "N/A":
                row[key] = RULES["fill_value"]

    # Fix: department correction - if team is MISSING and rating < 50, set team to "review_needed"
    for row in filtered:
        team = row.get("team", "")
        if team == "MISSING" and int(row["rating"]) < 50:
            row["team"] = "review_needed"

    # Fix: sort by rating descending, then by name ascending
    filtered.sort(key=lambda r: (-int(r["rating"]), r["name"]))

    with open(os.path.join(output_dir, "clean.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=["id", "name", "rating", "team"])
        writer.writeheader()
        for row in filtered:
            writer.writerow(row)


if __name__ == "__main__":
    run()

