import csv
import os

# Fixed rules
RULES = {
    "fill_value": "MISSING",
    "dedup_keep": "highest",
    "sort_by": "name",
    "range_min": 0,
    "range_max": 100,
}


def run():
    input_path = "data/input/records.csv"
    output_dir = "data/output"
