    with open(input_path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Deduplication: keep row with highest rating
    seen_ids = {}
    for row in rows:
        rid = row["id"]
        try:
            rating = int(row["rating"])
        except (ValueError, TypeError):
            rating = None

        # Store the original row but ensure rating is stored as int for comparison
        if rid not in seen_ids or (rating is not None and (seen_ids[rid]["_rating"] is None or rating > seen_ids[rid]["_rating"])):
            seen_ids[rid] = {**row, "_rating": rating}
    deduped = list(seen_ids.values())

