    # Fill missing values
    for row in filtered:
        for key in row:
            if key.startswith('_'):
                continue
            if row[key] == "" or row[key] is None:
                row[key] = RULES["fill_value"]

    # Department correction: if division is MISSING and rating < 50, set to review_needed
    for row in filtered:
        if row["division"] == "MISSING" and row["_rating"] < 50:
            row["division"] = "review_needed"

