    output_dir = "data/output"
    os.makedirs(output_dir, exist_ok=True)

    with open(input_path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    # Fix: dedup by id, keep highest rating
    seen_ids = {}
    for row in rows:
        rid = row["id"]
        rating = safe_int(row["rating"])
        if rid not in seen_ids or (rating is not None and rating > seen_ids[rid].get("_rating", float("-inf"))):
            seen_ids[rid] = row.copy()
            seen_ids[rid]["_rating"] = rating  # Store as int

    deduped = list(seen_ids.values())

    # Fix: filter by range 0-100 inclusive
    filtered = []
    for row in deduped:
        rating = row.get("_rating")
        if rating is not None and RULES["range_min"] <= rating <= RULES["range_max"]:
            filtered.append(row)

    # Fill missing values (empty string or N/A)
    for row in filtered:
        for key in row:
            val = row[key]
            if val == "" or val is None or val == "N/A":
                row[key] = RULES["fill_value"]

    # Fix: department correction - if team is MISSING and rating < 50, set team to "review_needed"
    for row in filtered:
        rating = row.get("_rating", 0)
        team = row.get("team", "")
        if team == "MISSING" and rating < 50:
            row["team"] = "review_needed"

    # Fix: sort by rating descending, then by name ascending
    filtered.sort(key=lambda r: (-r["_rating"], r["name"]))

    with open(os.path.join(output_dir, "clean.csv"), "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=["id", "name", "rating", "team"])
        writer.writeheader()
        for row in filtered:
            # Remove _rating before writing
            row_out = {k: v for k, v in row.items() if k not in ("_rating",)}
            writer.writerow(row_out)


if __name__ == "__main__":
    run()
